42	struct RecursionCtx<'a, 'v> {
43	    cg: &'a CallGraph,
44	    graph: &'a ScopeGraph,
45	    parsed: &'a ParsedFile,
46	    generic_params: BTreeSet<String>,
47	    file: FileId,
48	    at_byte: usize,
49	    module_scope: ScopeId,
50	    caller: &'a FunctionId,
51	    visit: &'v mut TypeVisit,
52	    depth: usize,
