54	
55	impl<'a, 'v> RecursionCtx<'a, 'v> {
56	    fn descend<T>(&mut self, f: impl FnOnce(&mut RecursionCtx<'a, '_>) -> T) -> T {
57	        let mut child = RecursionCtx {
58	            cg: self.cg,
59	            graph: self.graph,
60	            parsed: self.parsed,
61	            generic_params: self.generic_params.clone(),
62	            file: self.file,
63	            at_byte: self.at_byte,
64	            module_scope: self.module_scope,
65	            caller: self.caller,
66	            visit: self.visit,
67	            depth: self.depth + 1,
68	        };
69	        f(&mut child)
70	    }
71	}
