73	impl<'a> RustReceiverTyper<'a> {
74	    pub fn new(cg: &'a CallGraph) -> Self {
75	        // only valid with a complete scope graph
76	        let graph = cg
77	            .scope_graph
78	            .as_ref()
79	            .expect("RustReceiverTyper requires a populated scope graph");
80	        Self { cg, graph }
81	    }
82	
83	    pub fn type_of_receiver(&self, ctx: ReceiverTypeCtx<'_>) -> Option<ReceiverOutcome> {
84	        if !matches!(ctx.parsed.language, crate::languages::Language::Rust) {
85	            return None;
86	        }
87	        let file = self.graph.file_paths.get(&ctx.caller.file).copied()?;
88	        let module_scope = module_scope_for_byte(self.graph, file, ctx.fn_node.start_byte())?;
89	        let mut visit = TypeVisit::default();
90	        let mut recursion = RecursionCtx {
91	            cg: self.cg,
92	            graph: self.graph,
93	            parsed: ctx.parsed,
94	            generic_params: enclosing_generic_type_params(ctx.parsed, ctx.fn_node),
95	            file,
96	            at_byte: ctx.call_start_byte,
97	            module_scope,
98	            caller: ctx.caller,
99	            visit: &mut visit,
100	            depth: 0,
101	        };
102	        if let Some(node) = ctx.receiver_expr {
103	            type_of_node(&mut recursion, node)
104	        } else {
105	            type_of_expr(&mut recursion, ctx.qualifier?)
106	        }
107	    }
108	}
109	
110	fn type_of_expr(ctx: &mut RecursionCtx<'_, '_>, expr: &str) -> Option<ReceiverOutcome> {
111	    if ctx.depth > MAX_RECEIVER_TYPE_DEPTH {
112	        return None;
113	    }
114	    let expr = expr.trim();
115	    if matches!(expr, "self" | "Self") {
116	        return self_receiver_type(ctx);
117	    }
118	    if let Some((base, field)) = split_field_expr(expr) {
119	        return ctx.descend(|ctx| field_type_from_base(ctx, base, field));
120	    }
121	    if let Some(function) = split_call_expr(expr) {
122	        return ctx.descend(|ctx| return_type_from_call(ctx, function));
123	    }
124	    if is_simple_ident(expr) {
125	        return ctx.descend(|ctx| local_receiver_type(ctx, expr));
126	    }
127	    None
128	}
129	
130	fn type_of_node<'a>(
131	    ctx: &mut RecursionCtx<'a, '_>,
132	    node: tree_sitter::Node<'a>,
133	) -> Option<ReceiverOutcome> {
134	    if ctx.depth > MAX_RECEIVER_TYPE_DEPTH {
135	        return None;
136	    }
137	    match node.kind() {
138	        "call_expression" => {
139	            if let Some(call) = method_call_parts(ctx.parsed, node) {
140	                return ctx.descend(|ctx| method_chain_type(ctx, call));
141	            }
142	            let function = node
143	                .child_by_field_name("function")
144	                .or_else(|| node.child_by_field_name("name"))?;
145	            let function_text = ctx.parsed.node_text(&function).trim().to_string();
146	            ctx.descend(|ctx| return_type_from_call(ctx, &function_text))
147	        }
148	        "field_expression" => {
149	            let base = node.child_by_field_name("value")?;
150	            let field = node.child_by_field_name("field")?;
151	            let field_text = ctx.parsed.node_text(&field).trim().to_string();
152	            if !is_simple_ident(&field_text) {
153	                return None;
154	            }
155	            ctx.descend(|ctx| field_type_from_node_base(ctx, base, &field_text))
156	        }
157	        _ => {
158	            let expr = ctx.parsed.node_text(&node).trim().to_string();
159	            type_of_expr(ctx, &expr)
160	        }
161	    }
162	}
163	
164	fn self_receiver_type(ctx: &RecursionCtx<'_, '_>) -> Option<ReceiverOutcome> {
165	    let owner_scope = owner_scope_for_method(ctx)?;
166	    outcome_for_type_key(
167	        ctx.graph,
168	        TypeKey::InRepo(owner_scope),
169	        ReceiverRecovery::TypedParam,
170	    )
171	}
172	
173	fn local_receiver_type(ctx: &mut RecursionCtx<'_, '_>, name: &str) -> Option<ReceiverOutcome> {
174	    let binding = lookup_visible_binding(ctx.graph, ctx.file, ctx.at_byte, name)?;
175	    let def_byte = binding.vis_extents.first()?.lo.byte;
176	    if !ctx.visit.locals.insert((ctx.file, def_byte)) {
177	        return None;
178	    }
179	    let binding_module_scope =
180	        module_scope_for_byte(ctx.graph, ctx.file, def_byte).unwrap_or(ctx.module_scope);
181	    let fact = ctx.graph.local_facts.get(&(ctx.file, def_byte))?;
182	    let result = ctx.descend(|ctx| {
183	        ctx.at_byte = def_byte;
184	        ctx.module_scope = binding_module_scope;
185	        type_from_local_fact(ctx, fact)
186	    });
187	    ctx.visit.locals.remove(&(ctx.file, def_byte));
188	    result
189	}
190	
191	fn type_from_local_fact<'a>(
192	    ctx: &mut RecursionCtx<'a, '_>,
193	    fact: &LocalFact,
194	) -> Option<ReceiverOutcome> {
195	    if matches!(fact.kind, BindingKind::Param | BindingKind::Let) {
196	        if let Some(annotation) = fact.annotation.as_deref() {
197	            let recovery = match fact.kind {
198	                BindingKind::Param => ReceiverRecovery::TypedParam,
199	                BindingKind::Let => ReceiverRecovery::TypedLet,
200	                BindingKind::Pattern => unreachable!(),
201	            };
202	            return type_from_annotation(ctx, annotation, recovery);
203	        }
204	    }
205	    // A destructuring/tuple/struct pattern binding's type is NOT its initializer's
206	    // type: `let Pair(x, _) = a.pair();` binds `x` to a FIELD of Pair, not Pair.
207	    // Only a plain `let x = <init>` binds the whole initializer to the name, so
208	    // init-based type recovery is sound only for `BindingKind::Let`.
209	    if !matches!(fact.kind, BindingKind::Let) {
210	        return None;
211	    }
212	    match fact.init.as_ref()? {
213	        InitExpr::Ctor(expr) => {
214	            let ty = ctor_type_syntax(expr)?;
215	            type_from_annotation(ctx, ty, ReceiverRecovery::ConstructorLocal)
216	        }
217	        InitExpr::Field(expr) => {
218	            let (base, field) = split_field_expr(expr)?;
219	            ctx.descend(|ctx| field_type_from_base(ctx, base, field))
220	        }
221	        InitExpr::Call(expr) => {
222	            if let Some(node) = call_init_node_at(ctx) {
223	                return ctx.descend(|ctx| type_of_node(ctx, node));
224	            }
225	            let function = split_call_expr(expr)?;
226	            ctx.descend(|ctx| return_type_from_call(ctx, function))
227	        }
228	        InitExpr::Other => None,
229	    }
230	}
231	
232	fn type_from_annotation(
233	    ctx: &RecursionCtx<'_, '_>,
234	    annotation: &str,
235	    default_recovery: ReceiverRecovery,
236	) -> Option<ReceiverOutcome> {
237	    let type_syntax = peel_type(annotation);
238	    if type_syntax.is_empty() {
239	        return None;
240	    }
241	    let recovery = if std_wrapper_was_peeled(annotation) {
242	        ReceiverRecovery::StdWrapperPeel
243	    } else {
244	        default_recovery
245	    };
246	    let bare = owner_key(&type_syntax);
247	    match crate::resolution_identity::resolve_type_path_to_type_scope(
248	        ctx.graph,
249	        ctx.module_scope,
250	        &type_syntax,
251	    ) {
252	        Some(key) => Some(ReceiverOutcome {
253	            key: receiver_key(key),
254	            bare,
255	            recovery,
256	        }),
257	        None if is_enclosing_generic_type_param(ctx, &type_syntax) => None,
258	        None => Some(ReceiverOutcome {
259	            key: ReceiverTypeKey::Bare(bare.clone()),
260	            bare,
261	            recovery,
262	        }),
263	    }
264	}
265	
266	fn is_enclosing_generic_type_param(ctx: &RecursionCtx<'_, '_>, type_syntax: &str) -> bool {
267	    is_simple_ident(type_syntax) && ctx.generic_params.contains(type_syntax)
268	}
269	
270	fn field_type_from_base(
271	    ctx: &mut RecursionCtx<'_, '_>,
272	    base: &str,
273	    field: &str,
274	) -> Option<ReceiverOutcome> {
275	    let base_ty = type_of_expr(ctx, base)?;
276	    let ReceiverTypeKey::InRepo(owner_scope) = base_ty.key else {
277	        return None;
278	    };
279	    let key = certain_index_type(ctx.cg.field_types.get(&(owner_scope, field.to_string()))?)?;
280	    outcome_for_type_key(ctx.graph, key, ReceiverRecovery::FieldTyped)
281	}
282	
283	fn field_type_from_node_base<'a>(
284	    ctx: &mut RecursionCtx<'a, '_>,
285	    base: tree_sitter::Node<'a>,
286	    field: &str,
287	) -> Option<ReceiverOutcome> {
288	    let base_ty = type_of_node(ctx, base)?;
289	    let ReceiverTypeKey::InRepo(owner_scope) = base_ty.key else {
290	        return None;
291	    };
292	    let key = certain_index_type(ctx.cg.field_types.get(&(owner_scope, field.to_string()))?)?;
293	    outcome_for_type_key(ctx.graph, key, ReceiverRecovery::FieldTyped)
294	}
295	
296	fn return_type_from_call(
297	    ctx: &mut RecursionCtx<'_, '_>,
298	    function: &str,
299	) -> Option<ReceiverOutcome> {
300	    if ctx.depth > MAX_RECEIVER_TYPE_DEPTH {
301	        return None;
302	    }
303	    let fid = resolve_function_to_fid(ctx, function)?;
304	    if !ctx.visit.fns.insert(fid.clone()) {
305	        return None;
306	    }
307	    let key = ctx.cg.return_types.get(&fid).and_then(|entries| {
308	        certain_index_type(entries)
309	            .and_then(|key| outcome_for_type_key(ctx.graph, key, ReceiverRecovery::ReturnTyped))
310	    });
311	    ctx.visit.fns.remove(&fid);
312	    key
313	}
314	
315	fn method_chain_type<'a>(
316	    ctx: &mut RecursionCtx<'a, '_>,
317	    call: MethodCallParts<'a>,
318	) -> Option<ReceiverOutcome> {
319	    let recv_ty = type_of_node(ctx, call.receiver)?;
320	    let recovery = recv_ty.recovery;
321	    let ReceiverTypeKey::InRepo(scope) = recv_ty.key else {
322	        return None;
323	    };
324	    let fid = dispatch_method_single_exact(
325	        ctx.cg,
326	        scope,
327	        call.method,
328	        recovery,
329	        Some(call.arg_count),
330	        false,
331	    )?;
332	    if !ctx.visit.fns.insert(fid.clone()) {
333	        return None;
334	    }
335	    let result = ctx.cg.return_types.get(&fid).and_then(|entries| {
336	        let key = certain_index_type(entries)?;
337	        if !matches!(&key, TypeKey::InRepo(_)) {
338	            return None;
339	        }
340	        outcome_for_type_key(ctx.graph, key, ReceiverRecovery::ReturnTyped)
341	    });
342	    ctx.visit.fns.remove(&fid);
343	    result
344	}
345	
346	fn dispatch_method_single_exact(
347	    cg: &CallGraph,
348	    scope: ScopeId,
349	    method: &str,
350	    recovery: ReceiverRecovery,
351	    arg_count: Option<usize>,
352	    arg_spread: bool,
353	) -> Option<FunctionId> {
354	    if recovery == ReceiverRecovery::StdWrapperPeel {
355	        return None;
356	    }
357	    let cands = cg.methods_by_scope.get(&(scope, method.to_string()))?;
358	    let kept: Vec<&FunctionId> = cands
359	        .iter()
360	        .filter(|fid| {
361	            let Some(fact) = cg.method_facts.get(*fid) else {
362	                return false;
363	            };
364	            fact.has_self
365	                && !matches!(
366	                    arg_count,
367	                    Some(n) if !arg_spread && fact.arity_excl_self != n
368	                )
369	        })
370	        .collect();
371	    match kept.as_slice() {
372	        [fid]
373	            if matches!(
374	                cg.method_facts.get(*fid),
375	                Some(fact) if matches!(&fact.kind, MethodKind::Inherent)
376	            ) =>
377	        {
378	            Some((*fid).clone())
379	        }
380	        _ => None,
381	    }
382	}
383	
384	fn resolve_function_to_fid(ctx: &RecursionCtx<'_, '_>, function: &str) -> Option<FunctionId> {
385	    let function = function.trim();
386	    if function.contains('.') {
387	        return None;
388	    }
389	    let from = enclosing_scope(ctx.graph, ctx.file, ctx.at_byte)?;
390	    let target = if function.contains("::") {
391	        let (anchor, path) = rust_path_anchor(function)?;
392	        let policy = RustPolicy::new(ctx.graph, ctx.graph.edition);
393	        let at = SourceLoc {
394	            file: ctx.file,
395	            byte: ctx.at_byte,
396	        };
397	        let res = resolve_path(
398	            ctx.graph, &path, NS_VALUE, &anchor, from, NS_TYPE, &at, &policy,
399	        );
400	        single_callable_target(res.status, res.candidates.as_slice())?
401	    } else {
402	        let q = ResolveQuery {
403	            name: function.to_string(),
404	            ns: NS_VALUE,
405	            from,
406	            at: SourceLoc {
407	                file: ctx.file,
408	                byte: ctx.at_byte,
409	            },
410	            cfg: CfgCtx::default(),
411	            ctx: PolicyQueryCtx::default(),
412	        };
413	        let policy = RustPolicy::new(ctx.graph, ctx.graph.edition);
414	        let res = resolve(ctx.graph, &q, &policy);
415	        single_callable_target(res.status, res.candidates.as_slice())?
416	    };
417	    target_to_function_id(ctx, &target)
418	}
419	
420	fn target_to_function_id(ctx: &RecursionCtx<'_, '_>, target: &Target) -> Option<FunctionId> {
421	    if !matches!(target, Target::Item { callable: true, .. }) {
422	        return None;
423	    }
424	    let mut ids = Vec::new();
425	    for binding in &ctx.graph.bindings {
426	        if !matches!(&binding.target, BindTarget::Resolved(t) if t == target) {
427	            continue;
428	        }
429	        let Some(file) = graph_file_for_scope(ctx.graph, binding.scope) else {
430	            continue;
431	        };
432	        let owner = type_syntax_for_scope(ctx.graph, binding.scope);
433	        if let Some(functions) = ctx.cg.functions.get(&binding.name) {
434	            for fid in functions
435	                .iter()
436	                .filter(|fid| ctx.graph.file_paths.get(&fid.file).copied() == Some(file))
437	            {
438	                match owner.as_deref() {
439	                    Some(owner)
440	                        if ctx.cg.method_owners.get(fid).map(String::as_str) != Some(owner) =>
441	                    {
442	                        continue;
443	                    }
444	                    None if ctx.cg.method_owners.contains_key(fid) => continue,
445	                    _ => {}
446	                }
447	                if fid.file == ctx.caller.file || !ids.contains(fid) {
448	                    ids.push(fid.clone());
449	                }
450	            }
451	        }
452	    }
453	    match ids.as_slice() {
454	        [fid] => Some(fid.clone()),
455	        _ => None,
456	    }
457	}
458	
459	fn owner_scope_for_method(ctx: &RecursionCtx<'_, '_>) -> Option<ScopeId> {
460	    let mut scopes = BTreeSet::new();
461	    for ((scope, name), fids) in &ctx.cg.methods_by_scope {
462	        if name == &ctx.caller.name && fids.iter().any(|fid| fid == ctx.caller) {
463	            scopes.insert(*scope);
464	        }
465	    }
466	    match scopes.iter().copied().collect::<Vec<_>>().as_slice() {
467	        [scope] => Some(*scope),
468	        _ => None,
469	    }
470	}
471	
472	fn receiver_key(key: TypeKey) -> ReceiverTypeKey {
473	    match key {
474	        TypeKey::InRepo(scope) => ReceiverTypeKey::InRepo(scope),
475	        TypeKey::External(name) => ReceiverTypeKey::External(name),
476	    }
477	}
478	
479	fn outcome_for_type_key(
480	    graph: &ScopeGraph,
481	    key: TypeKey,
482	    recovery: ReceiverRecovery,
483	) -> Option<ReceiverOutcome> {
484	    let bare = match &key {
485	        TypeKey::InRepo(scope) => owner_key(&type_syntax_for_scope(graph, *scope)?),
486	        TypeKey::External(name) => owner_key(name),
487	    };
488	    Some(ReceiverOutcome {
489	        key: receiver_key(key),
490	        bare,
491	        recovery,
492	    })
493	}
494	
495	fn call_init_node_at<'a>(ctx: &RecursionCtx<'a, '_>) -> Option<tree_sitter::Node<'a>> {
496	    let mut node = ctx
497	        .parsed
498	        .tree
499	        .root_node()
500	        .descendant_for_byte_range(ctx.at_byte, ctx.at_byte.saturating_add(1))?;
501	    loop {
502	        if node.kind() == "let_declaration" {
503	            let value = node.child_by_field_name("value")?;
504	            return (value.kind() == "call_expression").then_some(value);
505	        }
506	        if node.kind() == "function_item" {
507	            return None;
508	        }
509	        node = node.parent()?;
510	    }
511	}
