513	#[derive(Clone, Copy)]
514	struct MethodCallParts<'a> {
515	    receiver: Node<'a>,
516	    method: &'a str,
517	    arg_count: usize,
518	}
519	
520	fn method_call_parts<'a>(parsed: &'a ParsedFile, call: Node<'a>) -> Option<MethodCallParts<'a>> {
521	    if call.kind() != "call_expression" {
522	        return None;
523	    }
524	    let function = call.child_by_field_name("function")?;
525	    if function.kind() != "field_expression" {
526	        return None;
527	    }
528	    let receiver = function.child_by_field_name("value")?;
529	    let field = function.child_by_field_name("field")?;
530	    if field.kind() != "field_identifier" {
531	        return None;
532	    }
533	    let method = parsed.node_text(&field).trim();
534	    if !is_simple_ident(method) {
535	        return None;
536	    }
537	    let arguments = call.child_by_field_name("arguments")?;
538	    Some(MethodCallParts {
539	        receiver,
540	        method,
541	        arg_count: rust_arg_count(arguments),
542	    })
543	}
544	
545	fn rust_arg_count(arguments: Node<'_>) -> usize {
546	    let mut cursor = arguments.walk();
547	    arguments
548	        .children(&mut cursor)
549	        .filter(|child| child.is_named())
550	        .count()
551	}
552	
553	fn certain_index_type(entries: &[(Option<String>, TypeKey)]) -> Option<TypeKey> {
554	    let mut key: Option<TypeKey> = None;
555	    for (_, candidate) in entries {
556	        match &key {
557	            Some(existing) if existing != candidate => return None,
558	            Some(_) => {}
559	            None => key = Some(candidate.clone()),
560	        }
561	    }
562	    key
563	}
564	
565	fn module_scope_for_byte(graph: &ScopeGraph, file: FileId, byte: usize) -> Option<ScopeId> {
566	    let mut scope = enclosing_scope(graph, file, byte)?;
567	    loop {
568	        let record = graph.scope(scope)?;
569	        if matches!(record.kind, ScopeKind::Root | ScopeKind::Module) {
570	            return Some(scope);
571	        }
572	        scope = graph.parent_of(scope)?;
573	    }
574	}
575	
576	fn enclosing_generic_type_params(
577	    parsed: &ParsedFile,
578	    fn_node: tree_sitter::Node<'_>,
579	) -> BTreeSet<String> {
580	    let mut params = BTreeSet::new();
581	    collect_direct_type_params(parsed, fn_node, &mut params);
582	
583	    let mut parent = fn_node.parent();
584	    while let Some(node) = parent {
585	        if node.kind() == "impl_item" {
586	            collect_direct_type_params(parsed, node, &mut params);
587	            break;
588	        }
589	        parent = node.parent();
590	    }
591	    params
592	}
593	
594	fn collect_direct_type_params(
595	    parsed: &ParsedFile,
596	    node: tree_sitter::Node<'_>,
597	    params: &mut BTreeSet<String>,
598	) {
599	    let mut cursor = node.walk();
600	    for child in node.named_children(&mut cursor) {
601	        if child.kind() != "type_parameters" {
602	            continue;
603	        }
604	        let mut param_cursor = child.walk();
605	        for param in child.named_children(&mut param_cursor) {
606	            if param.kind() == "type_parameter" {
607	                if let Some(name) = type_parameter_name(param) {
608	                    params.insert(parsed.node_text(&name).to_string());
609	                }
610	            }
611	        }
612	    }
613	}
614	
615	fn type_parameter_name(param: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
616	    let mut cursor = param.walk();
617	    let name = param
618	        .named_children(&mut cursor)
619	        .find(|child| matches!(child.kind(), "type_identifier" | "identifier"));
620	    name
621	}
622	
623	fn type_syntax_for_scope(graph: &ScopeGraph, scope: ScopeId) -> Option<String> {
624	    graph
625	        .bindings
626	        .iter()
627	        .find_map(|binding| match &binding.target {
628	            BindTarget::Resolved(Target::Item {
629	                owns: Some(owner), ..
630	            }) if *owner == scope => Some(binding.name.clone()),
631	            _ => None,
632	        })
633	}
634	
635	fn graph_file_for_scope(graph: &ScopeGraph, scope: ScopeId) -> Option<FileId> {
636	    graph
637	        .scope(scope)?
638	        .extents
639	        .first()
640	        .map(|extent| extent.file)
641	}
642	
643	fn split_field_expr(expr: &str) -> Option<(&str, &str)> {
644	    let (base, field) = expr.rsplit_once('.')?;
645	    if base.trim().is_empty() || !is_simple_ident(field.trim()) {
646	        return None;
647	    }
648	    Some((base.trim(), field.trim()))
649	}
650	
651	fn split_call_expr(expr: &str) -> Option<&str> {
652	    let function = expr
653	        .trim()
654	        .strip_suffix("(...)")
655	        .or_else(|| expr.trim().strip_suffix("()"))?;
656	    if function.contains('.') {
657	        return None;
658	    }
659	    Some(function.trim())
660	}
661	
662	fn ctor_type_syntax(expr: &str) -> Option<&str> {
663	    let expr = expr.trim();
664	    if let Some(function) = expr.strip_suffix("()") {
665	        return function.rsplit_once("::").map(|(ty, _)| ty.trim());
666	    }
667	    expr.strip_suffix("{}").map(str::trim)
668	}
669	
670	pub(crate) fn std_wrapper_was_peeled(annotation: &str) -> bool {
671	    let mut t = annotation.trim();
672	    loop {
673	        let before = t;
674	        t = t
675	            .trim_start_matches("&mut ")
676	            .trim_start_matches('&')
677	            .trim_start_matches("*const ")
678	            .trim_start_matches("*mut ")
679	            .trim_start_matches('*')
680	            .trim();
681	        if let Some(rest) = t.strip_prefix('\'') {
682	            let rest = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
683	            t = rest.trim().trim_start_matches("mut ").trim();
684	        }
685	        if t == before {
686	            break;
687	        }
688	    }
689	    ["Box", "Arc", "Rc", "Pin"].iter().any(|wrapper| {
690	        t.strip_prefix(wrapper)
691	            .is_some_and(|rest| rest.trim_start().starts_with('<'))
692	    })
693	}
694	
695	fn is_simple_ident(s: &str) -> bool {
696	    !s.is_empty() && s.chars().all(|c| c.is_alphanumeric() || c == '_')
697	}
698	
699	fn single_callable_target(status: ResStatus, candidates: &[Candidate]) -> Option<Target> {
700	    match (status, candidates) {
701	        (ResStatus::Resolved, [Candidate { target, .. }])
702	            if matches!(target, Target::Item { callable: true, .. }) =>
703	        {
704	            Some(target.clone())
705	        }
706	        _ => None,
707	    }
708	}
709	
710	fn rust_path_anchor(raw: &str) -> Option<(Anchor, RawPath)> {
711	    let mut segs: Vec<String> = raw.split("::").map(str::to_string).collect();
712	    if segs.is_empty() {
713	        return None;
714	    }
715	    let anchor = match segs.first().map(String::as_str) {
716	        Some("") => {
717	            segs.remove(0);
718	            Anchor {
719	                kind: AnchorKind::LeadingColon,
720	                prelude: None,
721	            }
722	        }
723	        Some("crate") => {
724	            segs.remove(0);
725	            Anchor::crate_root()
726	        }
727	        Some("self") => {
728	            segs.remove(0);
729	            Anchor::self_mod()
730	        }
731	        Some("super") => {
732	            let mut n = 0u32;
733	            while matches!(segs.first().map(String::as_str), Some("super")) {
734	                segs.remove(0);
735	                n += 1;
736	            }
737	            Anchor::super_n(n)
738	        }
739	        Some(_) => Anchor::bare(),
740	        None => return None,
741	    };
742	    Some((anchor, RawPath(segs)))
743	}
744	
745	#[cfg(test)]
746	mod tests;
