22	
23	#[derive(
24	    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
25	)]
26	pub enum ResolutionConfidence {
27	    Exact,
28	    NameOnly,
29	}
