53	impl ResolutionKind {
54	    pub fn as_str(&self) -> &'static str {
55	        match self {
56	            ResolutionKind::StaticLinkage => "static_linkage",
57	            ResolutionKind::QualifiedOwner => "qualified_owner",
58	            ResolutionKind::SelfReceiver => "self_receiver",
59	            ResolutionKind::ImportQualified => "import_qualified",
