76	}
77	
78	#[derive(Debug, Clone, PartialEq, Eq)]
79	pub struct ResolvedCallee<'a> {
80	    pub target: &'a FunctionId,
81	    pub confidence: ResolutionConfidence,
82	    pub kind: ResolutionKind,
83	}
84	
85	/// A resolved caller edge: who calls the seed, with what confidence, at which line.
86	#[derive(Debug, Clone, PartialEq, Eq)]
87	pub struct ResolvedCallEdge {
88	    pub caller: FunctionId,
89	    pub call_site_line: usize,
90	    pub confidence: ResolutionConfidence,
91	}
92	
93	/// Normalize an owner type's source text to its bare index key:
94	/// strip refs/pointers, smart-pointer wrappers are NOT peeled here (that is
95	/// receiver peeling, `peel_type`), strip generic args, strip `dyn `/`impl `.
96	pub fn owner_key(text: &str) -> String {
97	    let t = text.trim();
98	    let t = t.trim_start_matches("&mut ").trim_start_matches('&');
99	    let t = t.trim_start_matches('*');
100	    let t = t.trim_start_matches("dyn ").trim_start_matches("impl ");
101	    let t = t.split('<').next().unwrap_or(t);
102	    // C++ out-of-line `ns::Foo` declarator prefix -> last segment.
103	    let t = t.rsplit("::").next().unwrap_or(t);
104	    t.trim().to_string()
105	}
106	
107	/// Interface lookup key (Go): strip `&`/`*` and a `pkg.` qualifier to the bare
108	/// interface name. Returns `None` for a generic instantiation (`Foo[T]`), which
109	/// is non-dispatchable (a recorded gap, never a key) — spec §6/§10.
110	pub fn iface_key(text: &str) -> Option<String> {
111	    let t = text
112	        .trim()
113	        .trim_start_matches('&')
114	        .trim_start_matches('*')
115	        .trim();
116	    if t.contains('[') {
117	        return None; // generic instantiation -> gap, not a key
118	    }
119	    let bare = t.rsplit('.').next().unwrap_or(t).trim();
120	    if bare.is_empty() {
121	        None
122	    } else {
123	        Some(bare.to_string())
124	    }
125	}
126	
127	/// Admission key (Go method-set asymmetry): a value-receiver satisfier admits as
128	/// `T`; a pointer-receiver-only satisfier admits as `*T` (spec §7). Bare `T` must
129	/// already be normalized (no `pkg.`).
130	pub fn admission_key(bare_type: &str, is_pointer: bool) -> String {
131	    if is_pointer {
132	        format!("*{bare_type}")
133	    } else {
134	        bare_type.to_string()
135	    }
136	}
137	
138	/// Arity admission for interface-dispatch candidates (language-neutral; shared by
139	/// the resolution mint and the `interface_dispatch_manifest`). CONSERVATIVE on
140	/// purpose — the headline risk is recall loss (dropping a valid dispatch edge), so
141	/// a candidate is dropped ONLY on a confident exact mismatch and EVERY unknown
142	/// keeps it:
143	///   * a variadic candidate is never dropped (`a.variadic`),
144	///   * a spread call (`arg_spread`) drops nothing,
145	///   * an unknown `arg_count` (`None`) drops nothing,
146	///   * a candidate with no recorded `MethodArity` (`m == None`) is never dropped.
147	/// Only a known, non-spread call against a known, non-variadic method with a
148	/// different param count is provably-wrong and dropped.
149	pub fn arity_admits(arg_count: Option<usize>, arg_spread: bool, m: Option<&MethodArity>) -> bool {
150	    match (arg_count, m) {
151	        // Drop ONLY on a confident exact mismatch:
152	        (Some(n), Some(a)) if !arg_spread && !a.variadic => a.params == n,
153	        // Every unknown keeps the candidate (recall-safe):
154	        _ => true,
155	    }
156	}
157	
158	/// Filter interface-dispatch candidate ids by call arity, keeping each `id` iff
159	/// `arity_admits` admits its recorded `MethodArity` (a missing entry → unknown →
160	/// kept). Order-preserving; borrows the input slice.
161	pub fn arity_filter<'a>(
162	    impls: &'a [FunctionId],
163	    arg_count: Option<usize>,
164	    arg_spread: bool,
165	    method_arity: &BTreeMap<FunctionId, MethodArity>,
166	) -> Vec<&'a FunctionId> {
167	    impls
168	        .iter()
169	        .filter(|id| arity_admits(arg_count, arg_spread, method_arity.get(id)))
170	        .collect()
171	}
172	
173	/// Closed-list syntactic peel (spec section 2.3): refs/pointers and std wrappers,
174	/// recursively; then generic args; then dyn/impl. NEVER Deref-semantic.
175	pub fn peel_type(text: &str) -> String {
176	    let mut t = text.trim();
177	    loop {
178	        let before = t;
179	        t = t
180	            .trim_start_matches("&mut ")
181	            .trim_start_matches('&')
182	            .trim_start_matches("*const ")
183	            .trim_start_matches("*mut ")
184	            .trim_start_matches('*')
185	            .trim();
186	        // Rust lifetime after a reference: `&'a Sender` / `&'a mut Sender`.
