                    } else if let Some(right) = node.child_by_field_name("right") {
                        *found = self
                            .constructor_type(&right)
                            .map(|ty| (ty, ReceiverRecovery::ConstructorLocal));
                    } else {
                        *found = None;
                    }
                } else if self.node_binds_name(left, receiver) {
                    *bindings += 1;
                    *found = None;
                }
            }
