/// Node types that represent function/method definitions.
pub fn function_node_types(&self) -> Vec<&'static str> {
    match self {
        Self::Python => vec!["function_definition", "decorated_definition"],
        Self::JavaScript => vec![
            "function_declaration",
            "method_definition",
            "arrow_function",
            "function_expression",
            "generator_function_declaration",
        ],
        Self::TypeScript | Self::Tsx => vec![
            "function_declaration",
            "method_definition",
            "arrow_function",
            "function_expression",
            "generator_function_declaration",
        ],
        Self::Go => vec!["function_declaration", "method_declaration"],
        Self::Java => vec!["method_declaration", "constructor_declaration"],
        Self::C => vec!["function_definition"],
        Self::Cpp => vec!["function_definition", "template_declaration"],
        Self::Rust => vec!["function_item"],
        Self::Lua => vec!["function_declaration"],
        // Terraform: blocks (resource, variable, module, etc.) are the structural unit
        Self::Terraform => vec!["block"],
        Self::Bash => vec!["function_definition"],
    }
}

/// Whether a node kind is an identifier/variable reference.
pub fn is_identifier_node(&self, kind: &str) -> bool {
    // Common identifier types shared across most languages
    if matches!(
        kind,
        "identifier"
            | "shorthand_property_identifier"
            | "property_identifier"
            | "type_identifier"
            | "field_identifier"
            | "field_expression"
            | "qualified_identifier"
            | "namespace_identifier"
    ) {
        return true;
    }
    // Language-specific identifier types
    match self {
        Self::Terraform => kind == "variable_expr", // HCL: var.x, local.y
        Self::Bash => matches!(kind, "word" | "variable_name"),
        _ => false,
    }
}

/// Whether a node kind is a comment or string literal.
///
/// Used to filter out false-positive pattern matches that land inside
/// comments or string literals rather than actual code.
pub fn is_comment_or_string_node(&self, kind: &str) -> bool {
    // Comments — nearly universal across tree-sitter grammars
    if matches!(
        kind,
        "comment" | "line_comment" | "block_comment" | "doc_comment"
    ) {
        return true;
    }
    // String literals — language-specific
    match self {
        Self::Python => matches!(kind, "string" | "concatenated_string" | "string_content"),
        Self::JavaScript | Self::TypeScript | Self::Tsx => matches!(
            kind,
            "string" | "template_string" | "string_fragment" | "template_literal_type"
        ),
        Self::Go => matches!(
            kind,
            "interpreted_string_literal" | "raw_string_literal" | "rune_literal"
        ),
        Self::Java => matches!(kind, "string_literal" | "character_literal" | "text_block"),
        Self::C | Self::Cpp => matches!(
            kind,
            "string_literal"
                | "char_literal"
                | "string_content"
                | "raw_string_literal"
                | "concatenated_string"
        ),
        Self::Rust => matches!(
            kind,
            "string_literal" | "raw_string_literal" | "char_literal" | "string_content"
        ),
        Self::Lua => matches!(kind, "string" | "string_content"),
        // Terraform/HCL uses quoted strings as identifiers (resource types,
        // variable names, etc.), so string literals are meaningful code — only
        // filter out comments.
        Self::Terraform => false,
        Self::Bash => matches!(
            kind,
            "string" | "raw_string" | "heredoc_body" | "string_content"
        ),
    }
}

/// Whether a node is an assignment expression.
pub fn is_assignment_node(&self, kind: &str) -> bool {
    match self {
        Self::Python => {
            matches!(
                kind,
                "assignment" | "augmented_assignment" | "named_expression"
            )
        }
        Self::JavaScript | Self::TypeScript | Self::Tsx => {
            matches!(
                kind,
                "assignment_expression" | "augmented_assignment_expression"
            )
        }
        Self::Go => matches!(kind, "assignment_statement" | "short_var_declaration"),
        Self::Java => matches!(kind, "assignment_expression"),
