        assert_eq!(s.receiver_type, None, "{path}");
        assert!(cg.resolve_call_site(&s).iter().all(|c| {
            c.kind != ResolutionKind::TypedParam && c.kind != ResolutionKind::ConstructorLocal
        }));
    }
}

